state.reserve:
uint32_t npu_cold_descriptor_reserve(struct npu_cold_descriptor_state *s, uint32_t arena,
    uint32_t epoch, uint32_t destination, uint32_t value, uint32_t before)
{
    uint32_t status = valid(s, arena, epoch, 1);

    if (status)
        return status;
    if (s->next < 6 || s->committed != s->published || s->committed == upper(s->next) ||
        destination != address(s, s->committed) || value != NPU_COLD_DESCRIPTOR_STATUS ||
        before != s->preimages[s->committed])
        return fail(s, NPU_COLD_DESCRIPTOR_ORDER);
    __atomic_store_n(&s->committed, s->committed + 1, __ATOMIC_RELEASE);
    return load(&s->fault) ? NPU_COLD_DESCRIPTOR_FAULT : NPU_COLD_DESCRIPTOR_OK;
}

state.publish:
uint32_t npu_cold_descriptor_publish(struct npu_cold_descriptor_state *s, uint32_t arena,
    uint32_t epoch, uint32_t destination, uint32_t readback)
{
    uint32_t status = valid(s, arena, epoch, 1);

    if (status)
        return status;
    if (s->next < 6 || s->committed != s->published + 1 || s->published == upper(s->next) ||
        destination != address(s, s->published) || readback != NPU_COLD_DESCRIPTOR_STATUS)
        return fail(s, NPU_COLD_DESCRIPTOR_PUBLISH);
    __atomic_store_n(&s->published, s->published + 1, __ATOMIC_RELEASE);
    return load(&s->fault) ? NPU_COLD_DESCRIPTOR_FAULT : NPU_COLD_DESCRIPTOR_OK;
}

state.finish:
uint32_t npu_cold_descriptor_finish(struct npu_cold_descriptor_state *s, uint32_t arena,
    uint32_t epoch, uint32_t reply, const volatile uint32_t *descriptors)
{
    uint32_t status = valid(s, arena, epoch, 1), i;

    if (status)
        return status;
    if (npu_cold_descriptor_reply_arena(s->next, reply, arena) != arena ||
        s->committed != upper(s->next) || s->published != s->committed ||
        (s->next < 6 ? !!descriptors : !descriptors || ((uintptr_t)descriptors & 3)))
        return fail(s, NPU_COLD_DESCRIPTOR_PUBLISH);
    if (s->next >= 6) {
        for (i = lower(s->next); i < upper(s->next); i++)
            if (descriptors[(i - lower(s->next)) * 4 + 1] != NPU_COLD_DESCRIPTOR_STATUS)
                return fail(s, NPU_COLD_DESCRIPTOR_PUBLISH);
        s->completed_tx |= 1u << (s->next - 6);
    }
    s->completed |= 1u << s->next;
    s->next++;
    s->active = 0;
    return load(&s->fault) ? NPU_COLD_DESCRIPTOR_FAULT : NPU_COLD_DESCRIPTOR_OK;
}

state.begin:
uint32_t npu_cold_descriptor_begin(struct npu_cold_descriptor_state *s, uint32_t arena,
    uint32_t epoch, uint32_t selector, const volatile uint32_t *descriptors)
{
    uint32_t step = npu_cold_descriptor_step(selector), i, status;

    if (!s)
        return NPU_COLD_DESCRIPTOR_ARGUMENT;
    if (!s->magic) {
        const unsigned char *bytes = (const unsigned char *)s;

        for (i = 0; i < sizeof(*s); i++)
            if (bytes[i])
                return NPU_COLD_DESCRIPTOR_REINITIALIZE;
        if (epoch != 1 || step || descriptors || !npu_cold_descriptor_arena_valid(arena))
            return fail(s, NPU_COLD_DESCRIPTOR_PLAN);
        s->epoch = 1;
        s->arena = arena;
        __atomic_store_n(&s->magic, NPU_COLD_DESCRIPTOR_MAGIC, __ATOMIC_RELEASE);
    }
    status = valid(s, arena, epoch, 0);
    if (status)
        return status;
    if (step != s->next || step == NPU_COLD_DESCRIPTOR_STEPS ||
        (step < 6 ? !!descriptors : !descriptors || ((uintptr_t)descriptors & 3)))
        return fail(s, NPU_COLD_DESCRIPTOR_ORDER);
    s->active = 1;
    if (step >= 6) {
        s->reserved_tx |= 1u << (step - 6);
        for (i = lower(step); i < upper(step); i++)
            s->preimages[i] = descriptors[(i - lower(step)) * 4 + 1];
    }
    return load(&s->fault) ? NPU_COLD_DESCRIPTOR_FAULT : NPU_COLD_DESCRIPTOR_OK;
}

state.host:
int npu_linux_control_cold_exchange(struct npu_linux_control *control,
				    const struct npu_bootstrap_packet *command,
				    u32 *value)
{
	struct npu_bootstrap_packet snapshot;
	struct npu_cold_packet packet;
	enum npu_client_result result;
	u32 ticket, output, descriptor, arena;
	int error;

	if (!control || !control->initialized || !command || !value)
		return -EINVAL;
	mutex_lock(&control->mutex);
	if (control->error) {
		error = control->error;
		goto unlock;
	}
	if (control->closed || !control->provider) {
		error = hold(control, -ESHUTDOWN);
		goto unlock;
	}
	snapshot = *command;
	descriptor = npu_cold_descriptor_command_step(&snapshot);
	if (descriptor < NPU_COLD_DESCRIPTOR_STEPS && descriptor != control->descriptor_gets) {
		error = hold(control, -EPROTO);
		goto unlock;
	}
	ticket = npu_cold_client_request(&control->client, &packet,
					 sizeof(packet), &snapshot);
	if (!ticket) {
		error = hold(control, -EPROTO);
		goto unlock;
	}
	error = airoha_npu_wlan_control(control->provider, &packet, sizeof(packet));
	result = npu_cold_client_complete(&control->client, ticket, error,
					  &packet, sizeof(packet), &snapshot, &output);
	if (error || result != NPU_CLIENT_ACCEPTED)
		error = hold(control, error < 0 ? error : error ? -EIO : -EPROTO);
	else {
		if (descriptor < NPU_COLD_DESCRIPTOR_STEPS) {
			arena = npu_cold_descriptor_reply_arena(descriptor, output, control->descriptor_arena);
			if (!arena) {
				error = hold(control, -EPROTO);
				goto unlock;
			}
			control->descriptor_arena = arena;
			control->descriptor_gets++;
		}
		*value = output;
	}
unlock:
	mutex_unlock(&control->mutex);
	return error;
}

state.codec:
enum npu_client_result npu_cold_client_complete(struct npu_control_v2_client *s,
    uint32_t ticket, int error, const void *packet, uint32_t bytes,
    const struct npu_bootstrap_packet *command, uint32_t *value)
{
    uint32_t i, result, descriptor;

    if (!ticket || ticket != s->base.pending || s->base.phase == NPU_CLIENT_FAILED)
        return NPU_CLIENT_IGNORED;
    if (error)
        return fail(s, NPU_CLIENT_V2_ENVELOPE);
    if (!packet || bytes != NPU_COLD_SIZE || !command || !value ||
        s->base.phase != NPU_CLIENT_PARKED || s->base.operation != NPU_COLD_PENDING_OPERATION)
        return fail(s, NPU_CLIENT_V2_ARGUMENT);
    if (read_word(packet, 0) != NPU_CONTROL_HEADER || read_word(packet, 1) != NPU_COLD_API ||
        read_word(packet, 2) != NPU_COLD_REPLY || read_word(packet, 3) != NPU_COLD_VERSION ||
        read_word(packet, 4) != NPU_COLD_SIZE || read_word(packet, 5) != 1 ||
        read_word(packet, 6) != ticket || read_word(packet, 7) != s->base.nonce_lo ||
        read_word(packet, 8) != s->base.nonce_hi || read_word(packet, 9) != s->boot_lo ||
        read_word(packet, 10) != s->boot_hi || read_word(packet, 11) != command->header ||
        read_word(packet, 12) != command->api || read_word(packet, 14) != NPU_COLD_OK)
        return fail(s, NPU_CLIENT_V2_ENVELOPE);
    for (i = 15; i < 20; i++)
        if (read_word(packet, i))
            return fail(s, NPU_CLIENT_V2_ENVELOPE);
    result = read_word(packet, 13);
    descriptor = npu_cold_descriptor_command_step(command);
    if (descriptor < NPU_COLD_DESCRIPTOR_STEPS ?
        !npu_cold_descriptor_reply_arena(descriptor, result, 0) :
        result != (command->header == 0x30 && command->api == 10 ? 0x457u : command->value))
        return fail(s, NPU_CLIENT_V2_ENVELOPE);
    s->base.pending = 0;
    *value = result;
    return NPU_CLIENT_ACCEPTED;
}

